import{_ as t,a,b as s,c as r,d as o,e as l,f as i,g as n}from"./chunks/leg-8.DS09J6mb.js";import{_ as d,o as h,c,a5 as m}from"./chunks/framework.DGp912Ge.js";const k=JSON.parse('{"title":"Leg module Attachment/Detachment","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/maintenance/leg-module.md","filePath":"manual/maintenance/leg-module.md","lastUpdated":1785806767000}'),u={name:"manual/maintenance/leg-module.md"};function p(b,e,g,f,w,_){return h(),c("div",null,[...e[0]||(e[0]=[m('<h1 id="leg-module-attachment-detachment" tabindex="-1">Leg module Attachment/Detachment <a class="header-anchor" href="#leg-module-attachment-detachment" aria-label="Permalink to &quot;Leg module Attachment/Detachment&quot;">​</a></h1><p>This manual explains the disassembly and assembly sequence of the RBQ10 leg module. The instructions are based on the front left leg, and since the other legs have a symmetrical structure, the same method should be used for the disassembly and assembly process.</p><p><b>Fastening specification</b></p><table><tr><th>Parameter</th><th>Specification</th></tr><tr><td>Hex wrench</td><td>4mm</td></tr><tr><td>Q’ty</td><td>6 bolts in total</td></tr><tr><td>Spring washer</td><td>M5</td></tr></table><h2 id="leg-module-disassembly" tabindex="-1">Leg module disassembly <a class="header-anchor" href="#leg-module-disassembly" aria-label="Permalink to &quot;Leg module disassembly&quot;">​</a></h2><p>The bolts fastening the leg module are placed as shown below.</p><figure><img src="'+t+'" alt="Leg module bolt layout"></figure><h3 id="step-1-unscrew-the-bolts-dispose-of-the-used-m5-spring-washers" tabindex="-1">Step 1. Unscrew the bolts. (Dispose of the used M5 spring washers) <a class="header-anchor" href="#step-1-unscrew-the-bolts-dispose-of-the-used-m5-spring-washers" aria-label="Permalink to &quot;Step 1. Unscrew the bolts. (Dispose of the used M5 spring washers)&quot;">​</a></h3><h3 id="step-2-pull-the-leg-module-outward-after-the-bolts-are-unscrewed" tabindex="-1">Step 2. Pull the leg module outward after the bolts are unscrewed. <a class="header-anchor" href="#step-2-pull-the-leg-module-outward-after-the-bolts-are-unscrewed" aria-label="Permalink to &quot;Step 2. Pull the leg module outward after the bolts are unscrewed.&quot;">​</a></h3><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Be careful not to damage the com-wire by pulling it too far.</p></div></div><figure><img src="'+a+'" alt="Leg module removal"></figure><h3 id="step-3-pull-the-connector-handle-to-release-the-com-wire" tabindex="-1">Step 3. Pull the connector handle to release the com-wire. <a class="header-anchor" href="#step-3-pull-the-connector-handle-to-release-the-com-wire" aria-label="Permalink to &quot;Step 3. Pull the connector handle to release the com-wire.&quot;">​</a></h3><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Pulling the com-wire directly may cause disconnection. Make sure to pull the handle.</p></div></div><figure><img src="'+s+'" alt="Com-wire connector location"></figure><figure><img src="'+r+'" alt="Com-wire released by pulling the handle"></figure><h2 id="leg-module-assembly" tabindex="-1">Leg module assembly <a class="header-anchor" href="#leg-module-assembly" aria-label="Permalink to &quot;Leg module assembly&quot;">​</a></h2><p>The leg com-wire must be coiled once before assembly. If it is assembled without coiling, the com-wire may get pinched and damaged between the leg and the upper and lower plates.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>The spring washer for the bolts securing the leg is crucial for proper fastening. Be careful not to forget it during assembly.</p></div></div><h3 id="step-1-coil-the-com-wire-as-shown-in-the-picture-below" tabindex="-1">Step 1. Coil the com-wire as shown in the picture below. <a class="header-anchor" href="#step-1-coil-the-com-wire-as-shown-in-the-picture-below" aria-label="Permalink to &quot;Step 1. Coil the com-wire as shown in the picture below.&quot;">​</a></h3><figure><img src="'+o+'" alt="Coiling the com-wire"></figure><h3 id="step-2-align-the-red-dots-and-press-firmly-to-connect-the-com-wire" tabindex="-1">Step 2. Align the red dots and press firmly to connect the com-wire. <a class="header-anchor" href="#step-2-align-the-red-dots-and-press-firmly-to-connect-the-com-wire" aria-label="Permalink to &quot;Step 2. Align the red dots and press firmly to connect the com-wire.&quot;">​</a></h3><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Pushing the com-wire may cause disconnection. Make sure to press the handle.</p></div></div><figure><img src="'+l+'" alt="Connector mating"></figure><h3 id="step-3-insert-the-roll-frame-and-reducer-slot-into-the-body-frame" tabindex="-1">Step 3. Insert the roll frame and reducer slot into the body frame. <a class="header-anchor" href="#step-3-insert-the-roll-frame-and-reducer-slot-into-the-body-frame" aria-label="Permalink to &quot;Step 3. Insert the roll frame and reducer slot into the body frame.&quot;">​</a></h3><figure><img src="'+i+'" alt="Insert roll frame"></figure><h3 id="step-4-fasten-the-bolts-make-sure-to-insert-the-m5-spring-washers" tabindex="-1">Step 4. Fasten the bolts. (Make sure to insert the M5 spring washers) <a class="header-anchor" href="#step-4-fasten-the-bolts-make-sure-to-insert-the-m5-spring-washers" aria-label="Permalink to &quot;Step 4. Fasten the bolts. (Make sure to insert the M5 spring washers)&quot;">​</a></h3><figure><img src="'+n+'" alt="Tighten leg module bolts"></figure>',27)])])}const q=d(u,[["render",p]]);export{k as __pageData,q as default};
